 32:     /// <inheritdoc />
 33:     public async Task<ProcessRunResult> RunAsync(ProcessRunRequest request, CancellationToken ct = default)
 34:     {
 35:         ArgumentNullException.ThrowIfNull(request);
 36: 
 37:         try
 38:         {
 39:             using var process = new Process();
 40:             process.StartInfo.FileName = request.FileName;
 41:             if (request.ArgumentList is { Count: > 0 })
 42:             {
 43:                 foreach (var argument in request.ArgumentList)
 44:                     process.StartInfo.ArgumentList.Add(argument);
 45:             }
 46:             else
 47:             {
 48:                 process.StartInfo.Arguments = request.Arguments;
 49:             }
 50: 
 51:             process.StartInfo.RedirectStandardOutput = true;
 52:             process.StartInfo.RedirectStandardError = true;
 53:             process.StartInfo.UseShellExecute = false;
 54:             process.StartInfo.CreateNoWindow = true;
 55:             if (!string.IsNullOrWhiteSpace(request.WorkingDirectory))
 56:                 process.StartInfo.WorkingDirectory = request.WorkingDirectory;
 57: 
 58:             var opts = options.Value;
 59:             var token = string.IsNullOrWhiteSpace(request.GitHubTokenOverride)
 60:                 ? opts.GitHubToken
 61:                 : request.GitHubTokenOverride;
 62:             processEnvironment.ApplyAll(process.StartInfo, runAsUser: null, token);
 63:             if (request.EnvironmentVariables is not null)
 64:             {
 65:                 foreach (var variable in request.EnvironmentVariables)
 66:                 {
 67:                     if (variable.Value is null)
 68:                     {
 69:                         process.StartInfo.Environment.Remove(variable.Key);
 70:                     }
 71:                     else
 72:                     {
 73:                         process.StartInfo.Environment[variable.Key] = variable.Value;
 74:                     }
 75:                 }
 76:             }
 77: 
 78:             process.StartInfo.FileName = processEnvironment.ResolveExecutable(process.StartInfo, request.FileName);
 79: 
 80:             logger.LogDebug("Running {FileName} {Arguments} (cwd: {WorkingDirectory})", request.FileName, request.Arguments, process.StartInfo.WorkingDirectory);
 81:             if (OperatingSystem.IsWindows())
 82:             {
 83:                 return await RunWindowsJobContainedAsync(process.StartInfo, ct).ConfigureAwait(false);
 84:             }
 85: 
 86:             process.Start();
 87:             var stdoutTask = process.StandardOutput.ReadToEndAsync(ct);
 88:             var stderrTask = process.StandardError.ReadToEndAsync(ct);
 89:             await process.WaitForExitAsync(ct).ConfigureAwait(false);
 90:             var stdout = await stdoutTask.ConfigureAwait(false);
 91:             var stderr = await stderrTask.ConfigureAwait(false);
 92:             return new ProcessRunResult(process.ExitCode, stdout, string.IsNullOrWhiteSpace(stderr) ? null : stderr);
 93:         }
 94:         catch (TimeoutException)
 95:         {
 96:             throw;
 97:         }
 98:         catch (OperationCanceledException)
 99:         {
100:             throw;
101:         }
102:         catch (System.ComponentModel.Win32Exception ex)
103:         {
104:             logger.LogWarning(ex, "Process {FileName} not found", request.FileName);
105:             return new ProcessRunResult(-1, null, $"{request.FileName} not found.");
106:         }
107:         catch (Exception ex)
108:         {
109:             logger.LogError(ex, "Process {FileName} failed", request.FileName);
110:             return new ProcessRunResult(-1, null, ex.Message);
111:         }
112:     }
113: }

